const t=(a,b)=>getLocale()==='ar'?a:b,e=v=>WorkspaceUI.esc(v),uid=()=>crypto.randomUUID();
let actor=null,epoch=0,cap=null,list=[],total=0,loading=false,profile=null,editing=null,dirty=false,tab='list',notice='',draft=null,drafts=[],files=[],relations=[],statement=null,auditRows=[],importJob=null,scroll=0,columns=['fileNumber','fullName','nationality','type','companyId','status','phone','vehicles','facilities','collected','remaining','due','overdue','future','refunds','rating','completeness','alerts'],filters={},timer=null,preferenceTimer=null,observer=null,notifications=[],autoBusy=false,templateDraft={name:'',description:'',types:'',required:false,action:'issue',templateKey:'',fields:[]};
const names={fileNumber:['رقم الملف','File number'],fullName:['الاسم الكامل','Full name'],nationality:['الجنسية','Nationality'],type:['نوع العميل','Customer type'],companyId:['الشركة الحالية','Current company'],status:['حالة الملف','File status'],phone:['الهاتف الرئيسي','Primary phone'],vehicles:['المركبات','Vehicles'],facilities:['التسهيلات','Facilities'],collected:['المحصل','Collected'],remaining:['المتبقي','Remaining'],due:['المستحق','Due'],overdue:['المتأخرات','Overdue'],future:['المستحق مستقبلاً','Future due'],refunds:['المسترجع','Refunds'],rating:['التقييم','Rating'],completeness:['اكتمال البيانات','Completeness'],alerts:['التنبيهات','Alerts'],owner:['مالك','Owner'],owner_driver:['مالك وسائق','Owner and driver'],driver:['سائق','Driver'],Prospect:['محتمل','Prospect'],Active:['نشط','Active'],Suspended:['موقوف','Suspended'],Ended:['منتهي','Ended'],Archived:['مؤرشف','Archived'],valid:['صالح','Valid'],unverified:['غير متحقق','Unverified'],invalid:['غير صالح','Invalid'],inactive:['غير نشط','Inactive'],unknown:['غير معروف','Unknown'],granted:['موافق','Consented'],refused:['رافض','Refused'],withdrawn:['سحب الموافقة','Withdrawn'],emiratesId:['الهوية الإماراتية','Emirates ID'],passport:['جواز السفر','Passport'],driving:['رخصة القيادة','Driving licence'],residence:['الإقامة','Residence'],photo:['الصورة الشخصية','Photo'],undertaking:['تعهد','Undertaking'],other:['آخر','Other'],list:['سجل العملاء','Customer register'],personal:['البيانات الشخصية','Personal'],documents:['المستندات','Documents'],notes:['الملاحظات','Notes'],relations:['العلاقات والزيارات','Relationships & visits'],timeline:['السجل الزمني','Timeline'],financial:['المالية','Financial'],undertakings:['التعهدات','Undertakings'],calls:['الاتصالات والمتابعة','Calls & follow-up'],services:['الطلبات والمركبات','Requests & vehicles'],audit:['سجل التدقيق','Audit log'],no_answer:['يرن ولم يرد','Ringing, no answer'],off:['الهاتف مغلق','Phone off'],confirmed:['تم الرد وأكد الموعد','Answered, confirmed appointment'],rescheduled:['تم الرد وطلب موعداً جديداً','Answered, requested new appointment']};
Object.assign(names,{birthDate:['تاريخ الميلاد','Birth date'],sponsor:['الكفيل','Sponsor'],residencyEmployer:['جهة الإقامة','Residency employer'],address:['السكن','Address'],name:['الاسم','Name'],issue:['إصدار','Issue'],edit:['تعديل','Edit'],cancel:['إلغاء','Cancel'],note:['ملاحظة','Note'],agreement:['اتفاق','Agreement'],followup:['متابعة','Follow-up'],promise:['تعهد','Promise'],vehicle:['مركبة','Vehicle'],general:['عام','General'],verified:['مثبتة','Verified'],unconfirmed:['غير مؤكدة','Unconfirmed'],created:['إنشاء الملف','Profile created'],updated:['تحديث الملف','Profile updated'],transferred:['نقل الشركة','Company transfer'],status_changed:['تغيير الحالة','Status changed'],file_added:['إضافة مستند','Document added'],service_intent:['نية طلب خدمة','Service intent'],undertaking_completed:['استكمال تعهد','Undertaking completed'],rating_snapshot:['تحديث مصادر التقييم','Rating source update'],call:['اتصال','Call'],cooperation:['واقعة تعاون','Cooperation incident'],visit:['زيارة مشتركة','Joint visit']});
const label=k=>String(k).startsWith('undertaking:')?(profile?.completeness?.requirements.find(x=>x.id===String(k).slice(12))?.name||t('تعهد مطلوب','Required undertaking')):names[k]?t(...names[k]):k;
const error=k=>({customerSchemaPending:t('ترحيل العملاء المقترح لم يُطبق. لا يوجد حفظ محلي بديل.','Proposed customer migration has not been applied. No local storage fallback.'),officialDuplicateReviewRequired:t('معرّف رسمي مكرر؛ يلزم تفويض مراجعة وسبب موثق. لا دمج تلقائي.','Official identifier match requires authorized review and a documented reason; no automatic merge.'),revisionConflict:t('تغير السجل. أعد فتحه قبل الحفظ؛ بيانات النموذج باقية.','Record changed. Reopen before saving; entered data remains.'),denied:t('ليست لديك الصلاحية المطلوبة في هذه الشركة.','You lack the required company permission.'),fileQuarantined:t('الملف محجور حتى نجاح الفحص الفعلي.','File quarantined until a real scan succeeds.'),customerInactive:t('العميل غير نشط؛ الطلب الجديد يحتاج استثناء معتمداً. التحصيل غير معطل.','Customer is inactive; new requests need an authorized exception. Collection remains available.'),appointmentRequired:t('حدد تاريخ الموعد ووقته.','Enter appointment date and time.'),invalidPhone:t('استخدم رقماً دولياً يبدأ بـ +.','Use an international number beginning with +.'),required:t('أكمل الحقول الإلزامية.','Complete required fields.')})[k]||t('تعذر الإجراء؛ لم يُؤكد الحفظ. البيانات المدخلة باقية.','Action failed; saving was not confirmed. Entered data remains.')+' ('+k+')';
async function api(path,method='GET',body){const n=epoch,who=ABCentral?.actor?.id;const result=await ABCentral.api(path,method,body,method==='GET'?undefined:uid());if(n!==epoch||who!==ABCentral?.actor?.id)throw Error('staleSession');return result;}
const coName=id=>cap?.companies.find(c=>c.id===id)?.englishName||id;
const can=(a,co=profile?.companyId||editing?.companyId)=>cap?.companies.find(c=>c.id===co)?.rights.includes('customer_'+a);
const opt=(rows,value)=>'<option value="">—</option>'+rows.map(r=>`<option value="${e(r.id)}" ${String(value)===String(r.id)?'selected':''}>${e(r.name||r.englishName||label(r.id))}</option>`).join('');
function field(name,title,value='',type='text',choices=null,required=false){return `<label>${e(title)}${required?' *':''}${choices?`<select class="input" name="${name}" ${required?'required':''}>${opt(choices,value)}</select>`:type==='textarea'?`<textarea class="input" name="${name}" rows="4" maxlength="10000">${e(value)}</textarea>`:`<input class="input" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} maxlength="2000" />`}</label>`;}
const enums=a=>a.map(id=>({id,name:label(id)}));
const button=(action,title,id='')=>`<button class="ghost-btn" type="button" data-cu="${action}" data-id="${e(id)}">${e(title)}</button>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${heads.length}">${t('لا توجد بيانات','No data')}</td></tr>`}</tbody></table></div>`;
const form=(id,html,title=t('حفظ البيانات','Save data'))=>`<form id="${id}" class="form-grid">${html}<button type="submit" class="secondary-btn">${e(title)}</button></form>`;
function redraw(){if(app.state.currentPage==='customers'||app.state.currentPage==='notifications')render();}
function show(msg){notice=msg;const n=document.getElementById('cu-notice');if(n)n.textContent=msg;}
function reset(){templateDraft={name:'',description:'',types:'',required:false,action:'issue',templateKey:'',fields:[]};epoch++;clearTimeout(timer);clearTimeout(preferenceTimer);observer?.disconnect();actor=null;cap=null;list=[];total=0;profile=null;editing=null;dirty=false;draft=null;drafts=[];files=[];relations=[];statement=null;auditRows=[];importJob=null;notifications=[];loading=false;autoBusy=false;filters={};tab='list';notice='';}
async function load(){if(loading)return;loading=true;try{cap=await api('customers/capabilities');if(cap.available){const prefs=await api('customer-preferences');if(Array.isArray(prefs.columns)&&prefs.columns.length)columns=prefs.columns.filter(k=>names[k]);filters=prefs.filters||{};scroll=prefs.scroll||0;await fetchRows(true);drafts=(await api('customer-drafts')).rows;}}catch(err){if(err.message!=='staleSession')notice=error(err.message);}finally{loading=false;redraw();}}
async function fetchRows(replace){const q=new URLSearchParams({...filters,offset:String(replace?0:list.length),limit:'50'}),result=await api('customers?'+q);total=result.total;list=replace?result.rows:list.concat(result.rows.filter(r=>!list.some(x=>x.id===r.id)));}
function blank(){return {fullName:'',companyId:cap.companies.find(c=>c.status==='Active'&&c.rights.includes('customer_create'))?.id||'',type:'owner',status:'Prospect',nationality:'',birthDate:'',legacyData:{},sponsor:'',residencyEmployer:'',residencyCompanyId:null,phones:[],address:{emirate:'',areaId:'',details:'',location:'',verifiedOn:''},emergencyContacts:[],identityDocuments:[],notes:''};}
function leave(){return !dirty||confirm(t('توجد تعديلات غير محفوظة. هل تريد الانتقال؟ المسودة المحفوظة لا تعني حفظ الملف النهائي.','Unsaved changes remain. Leave this screen? A saved draft is not a saved final profile.'));}
async function open(id){if(!leave())return;scroll=window.scrollY;await prefs();profile=await api('customers/'+id);editing=null;dirty=false;draft=null;files=[];relations=[];statement=null;auditRows=[];tab='personal';redraw();window.scrollTo(0,0);}
async function prefs(){if(!cap?.available)return;await api('customer-preferences','POST',{columns,filters,scroll});}
function listHTML(){const options=(name,rows)=>`<details class="cu-filter"><summary>${name==='companies'?t('الشركات','Companies'):name==='types'?t('الأنواع','Types'):t('الحالات','Statuses')}</summary><input class="input" data-cu-filter-search placeholder="${t('بحث داخل الخيارات','Search options')}" />${rows.map(r=>`<label><input type="checkbox" data-cu-multi="${name}" value="${e(r.id)}" ${(filters[name]||'').split(',').includes(r.id)?'checked':''} />${e(r.name||r.englishName||label(r.id))}</label>`).join('')}</details>`;
return `<p>${t('الأرقام المالية والمركبات والتقييم تظهر غير متاحة حتى وجود مصادر فعلية مكتملة. لا أرصدة أو تصنيفات مفترضة.','Financial/vehicle/rating columns remain unavailable until complete real sources exist. No invented balances or classifications.')}</p><form id="cu-filters" class="form-grid">${field('q',t('الاسم أو الهاتف أو رقم الملف','Name, phone or file number'),filters.q||'')}${field('minNumber',t('من رقم','From number'),filters.minNumber||'','number')}${field('maxNumber',t('إلى رقم','To number'),filters.maxNumber||'','number')}${field('from',t('تاريخ الإنشاء من','Created from'),filters.from||'','date')}${field('to',t('إلى','To'),filters.to||'','date')}${field('direction',t('الترتيب الرقمي','Numeric order'),filters.direction||'asc','text',[{id:'asc',name:t('تصاعدي','Ascending')},{id:'desc',name:t('تنازلي','Descending')}])}<button type="submit" class="secondary-btn">${t('بحث / تصفية','Search / filter')}</button></form><div class="cu-filterbar">${options('companies',cap.companies)}${options('types',enums(['owner','owner_driver','driver']))}${options('statuses',enums(['Prospect','Active','Suspended','Ended','Archived']))}<details><summary>${t('الأعمدة وترتيبها','Columns & order')}</summary>${Object.keys(names).filter(k=>['fileNumber','fullName','nationality','type','companyId','status','phone','vehicles','facilities','collected','remaining','due','overdue','future','refunds','rating','completeness','alerts'].includes(k)).map(k=>`<div><label><input type="checkbox" data-cu-column="${k}" ${columns.includes(k)?'checked':''} />${e(label(k))}</label>${button('column-up','↑',k)}${button('column-down','↓',k)}</div>`).join('')}</details></div><p>${t('إجمالي العملاء','Total customers')}: ${total} — ${t('المحمّل','Loaded')}: ${list.length}</p>${table(columns.map(label),list.map(r=>columns.map(k=>k==='fullName'?button('open',r.fullName,r.id):k==='companyId'?e(coName(r.companyId)):k==='phone'&&r.phone?`<a href="tel:${e(r.phone)}">${e(r.phone)}</a>`:r[k]==null?t('غير متاح','Unavailable'):e(['type','status'].includes(k)?label(r[k]):r[k]))))}<div id="cu-sentinel">${list.length<total?button('more',t('تحميل المزيد','Load more')):t('نهاية السجل','End of register')}</div>`;}
function editor(){const d=editing;return `<h2>${profile?t('تعديل ملف العميل','Edit customer'):t('عميل جديد — لا يصدر رقم قبل الحفظ النهائي','New customer — no number until final save')}</h2><p>${t('الحد الأدنى: الاسم والشركة. بقية البيانات تستكمل لاحقاً.','Minimum: name and company. Other information may be completed later.')}</p><form id="cu-editor"><fieldset><legend>${t('البيانات الأساسية والإقامة','Basic & residency information')}</legend><div class="form-grid">${field('fullName',label('fullName'),d.fullName,'text',null,true)}${field('companyId',label('companyId'),d.companyId,'text',cap.companies.filter(c=>(c.status==='Active'||profile&&c.id===profile.companyId)&&c.rights.includes(profile?'customer_edit':'customer_create')),true)}${field('type',label('type'),d.type,'text',enums(['owner','owner_driver','driver']),true)}${field('status',label('status'),d.status,'text',enums(['Prospect','Active','Suspended','Ended','Archived']),true)}${field('nationality',label('nationality'),d.nationality)}${field('birthDate',t('تاريخ الميلاد','Birth date'),d.birthDate,'date')}${field('sponsor',t('الكفيل','Sponsor'),d.sponsor)}${field('residencyEmployer',t('جهة الإقامة الحالية','Residency employer'),d.residencyEmployer)}${field('residencyCompanyId',t('شركة الإقامة داخل المجموعة (اختياري)','Group residency company (optional)'),d.residencyCompanyId,'text',cap.companies)}</div></fieldset><fieldset><legend>${t('أرقام التواصل وموافقة التسويق لكل رقم','Contact numbers & consent per number')}</legend>${d.phones.map((p,i)=>`<div class="cu-repeat form-grid">${field('phone-'+i+'-number',t('الرقم الدولي','International number'),p.number,'tel',null,true)}${field('phone-'+i+'-status',t('صحة الرقم','Number status'),p.status,'text',enums(['valid','unverified','invalid','inactive']))}${field('phone-'+i+'-marketingConsent',t('موافقة التسويق','Marketing consent'),p.marketingConsent,'text',enums(['unknown','granted','refused','withdrawn']))}${field('phone-'+i+'-consentAt',t('تاريخ الموافقة','Consent date'),p.consentAt,'date')}${field('phone-'+i+'-consentEvidence',t('دليل الموافقة','Consent evidence'),p.consentEvidence)}<label><input type="checkbox" name="phone-${i}-primary" ${p.primary?'checked':''} />${t('رئيسي','Primary')}</label><label><input type="checkbox" name="phone-${i}-whatsapp" ${p.whatsapp?'checked':''} />WhatsApp</label>${button('phone-remove',t('إزالة من البيانات الحالية (التاريخ محفوظ)','Remove from current profile (history retained)'),String(i))}</div>`).join('')}${button('phone-add',t('إضافة رقم','Add number'))}</fieldset><fieldset><legend>${t('السكن الحالي — التاريخ السابق محفوظ في التدقيق','Current address — previous values retained in audit')}</legend><div class="form-grid">${field('emirate',t('الإمارة','Emirate'),d.address?.emirate,'text',(ABCentral.emirates||[]).map(x=>({id:x.id,name:getLocale()==='ar'?x.name_ar:x.name_en})))}${field('areaId',t('المنطقة التابعة للإمارة','Area within emirate'),d.address?.areaId,'text',(ABCentral.areas||[]).filter(x=>x.emirateId===d.address?.emirate||x.emirate_id===d.address?.emirate).map(x=>({id:x.id,name:x.name||x.nameAr||x.name_ar||x.nameEn||x.name_en})))}${field('addressDetails',t('تفاصيل السكن','Address details'),d.address?.details,'textarea')}${field('location',t('وصف الموقع / مرجعه','Location description / reference'),d.address?.location)}${field('verifiedOn',t('آخر تحقق من السكن','Last address verification'),d.address?.verifiedOn,'date')}</div></fieldset><fieldset><legend>${t('جهات الاتصال والطوارئ — لا صلاحيات مالية أو تسويقية تلقائية','Emergency contacts — no automatic financial/marketing authority')}</legend>${d.emergencyContacts.map((p,i)=>`<div class="cu-repeat form-grid">${['name','relationship','country','phone','lawfulBasis'].map(k=>field('emergency-'+i+'-'+k,t({name:'الاسم',relationship:'صلة القرابة',country:'الدولة',phone:'الهاتف',lawfulBasis:'أساس حفظ البيانات'}[k],k),p[k])).join('')}<label><input type="checkbox" name="emergency-${i}-whatsapp" ${p.whatsapp?'checked':''} />WhatsApp</label><label><input type="checkbox" name="emergency-${i}-homeCountryEmergency" ${p.homeCountryEmergency?'checked':''} />${t('طوارئ في البلد الأصلي','Home country emergency')}</label>${button('emergency-remove',t('إزالة من البيانات الحالية','Remove current contact'),String(i))}</div>`).join('')}${button('emergency-add',t('إضافة جهة اتصال','Add contact'))}</fieldset><fieldset><legend>${t('معرّفات ووثائق العميل','Customer identifiers & documents')}</legend><p>${t('رفع الوثائق من تبويب المستندات بعد حفظ الملف. لا يُحتسب الاستكمال قبل الفحص والتحقق.','Upload from Documents after saving the profile. Completion requires scanning and verification.')}</p>${['emiratesId','passport','driving','residence'].map(kind=>{const x=d.identityDocuments.find(x=>x.kind===kind)||{};return `<fieldset><legend>${label(kind)}</legend><div class="form-grid">${field(kind+'-number',t('الرقم','Number'),x.number)}${field(kind+'-issuedOn',t('الإصدار','Issued'),x.issuedOn,'date')}${field(kind+'-expiresOn',t('الانتهاء','Expiry'),x.expiresOn,'date')}${field(kind+'-verifiedVersionId',t('نسخة مفحوصة تم التحقق من صحتها','Scanned, human-verified version'),x.verifiedVersionId,'text',files.filter(f=>f.scanStatus==='clean'&&f.kind===kind).map(f=>({id:f.id,name:f.title+' v'+f.version})))}</div></fieldset>`;}).join('')}</fieldset><div class="form-grid">${field('notes',t('ملاحظات أساسية','Basic notes'),d.notes,'textarea')}${field('duplicateReview',t('سبب مراجعة معرّف رسمي مكرر (للمخول فقط)','Official duplicate review reason (authorized only)'),editing.duplicateReview||'','textarea')}</div><div id="cu-duplicates"></div><div class="cu-actions">${button('duplicate-check',t('فحص التشابه قبل الحفظ','Check similar files before save'))}<button type="submit" data-save-mode="save" class="secondary-btn">${t('حفظ','Save')}</button>${!profile?'<button type="submit" data-save-mode="new" class="ghost-btn">'+t('حفظ وإضافة عميل جديد','Save & add new customer')+'</button>':''}<button type="submit" data-save-mode="service" class="ghost-btn">${t('حفظ وإضافة خدمة','Save & add service')}</button>${button('cancel',t('إلغاء','Cancel'))}</div></form><p id="cu-autosave" role="status"></p>`;}
function readEditor(){const el=document.getElementById('cu-editor');if(!el||!editing)return;const f=new FormData(el);for(const k of ['fullName','companyId','type','status','nationality','birthDate','sponsor','residencyEmployer','notes'])editing[k]=String(f.get(k)||'');editing.residencyCompanyId=f.get('residencyCompanyId')||null;editing.duplicateReview=f.get('duplicateReview')||'';editing.address={emirate:f.get('emirate')||'',areaId:f.get('areaId')||'',details:f.get('addressDetails')||'',location:f.get('location')||'',verifiedOn:f.get('verifiedOn')||''};editing.phones=editing.phones.map((p,i)=>({...p,...Object.fromEntries(['number','status','marketingConsent','consentAt','consentEvidence'].map(k=>[k,String(f.get('phone-'+i+'-'+k)||'')])),primary:f.has('phone-'+i+'-primary'),whatsapp:f.has('phone-'+i+'-whatsapp')}));editing.emergencyContacts=editing.emergencyContacts.map((p,i)=>({...p,...Object.fromEntries(['name','relationship','country','phone','lawfulBasis'].map(k=>[k,String(f.get('emergency-'+i+'-'+k)||'')])),whatsapp:f.has('emergency-'+i+'-whatsapp'),homeCountryEmergency:f.has('emergency-'+i+'-homeCountryEmergency')}));editing.identityDocuments=['emiratesId','passport','driving','residence'].map(kind=>({kind,number:String(f.get(kind+'-number')||''),issuedOn:String(f.get(kind+'-issuedOn')||''),expiresOn:String(f.get(kind+'-expiresOn')||''),verifiedVersionId:f.get(kind+'-verifiedVersionId')||null})).filter(d=>d.number||d.issuedOn||d.expiresOn||d.verifiedVersionId);}
async function autosave(){if(!editing?.companyId||profile||autoBusy)return;autoBusy=true;const copy=structuredClone(editing);delete copy.duplicateReview;try{const result=await api('customer-drafts','POST',{...(draft?{id:draft.id,revision:draft.revision}:{}),companyId:copy.companyId,profile:copy});draft=result;const n=document.getElementById('cu-autosave');if(n)n.textContent=t('حُفظت المسودة على الخادم دون رقم رسمي.','Draft saved on server without an official number.');}catch(err){if(err.message!=='staleSession')show(error(err.message));}finally{autoBusy=false;}}
function header(){const p=profile;return `<header class="cu-profile-head"><div><h2>${e(p.fullName)} <small>#${e(p.fileNumber)}</small></h2><p>${e(p.nationality)} — ${e(label(p.type))} — ${e(label(p.status))} — ${e(coName(p.companyId))}</p></div><div class="cu-actions">${button('back',t('السجل','Register'))}${button('previous',t('السابق','Previous'))}${button('next',t('التالي','Next'))}<form id="cu-jump"><label>${t('رقم الملف','File number')}<input class="input" type="number" min="1" name="number" required /></label><button type="submit" class="ghost-btn">${t('انتقال','Go')}</button></form>${can('edit')?button('edit',t('تعديل','Edit')):''}</div></header><div class="cu-summary"><article><strong>${t('اكتمال الملف','Completeness')}: ${p.completeness.percent}%</strong><p>${p.completeness.missing.map(k=>e(label(k))).join('، ')}</p></article><article><strong>${t('التقييم','Rating')}: ${p.rating.classified?p.rating.total:t('غير مصنف','Unclassified')}</strong><p>${t('الأوزان 60/15/15/10؛ لا خصم بسبب غياب المصادر.','Weights 60/15/15/10; missing sources cause no penalty.')}</p></article><article><strong>${t('المالية والمركبات','Finance & vehicles')}</strong><p>${t('لا بيانات متكاملة؛ تفاصيل الحركات المرتبطة في تبويب المالية.','No complete data; linked posted movements appear under Finance.')}</p></article></div><p>${p.alerts.map(a=>e(a.kind==='address'?t('تحقق من عنوان العميل','Verify customer address'):label(a.document)+' '+a.date)).join(' — ')}</p><nav class="cu-tabs">${['personal','documents','undertakings','calls','financial','notes','relations','services','timeline',...(can('audit')?['audit']:[])].map(k=>button('tab',label(k),k)).join('')}</nav>`;}
function templateFieldsHTML(){return `<fieldset><legend>${t('حقول النموذج','Form fields')}</legend>${templateDraft.fields.map((f,i)=>`<div class="form-grid">${field('templateField-'+i+'-key',t('رمز الحقل (أحرف لاتينية دون مسافات)','Field key (Latin letters, no spaces)'),f.key,'text',null,true)}${field('templateField-'+i+'-label',t('عنوان الحقل','Field label'),f.label,'text',null,true)}${field('templateField-'+i+'-type',t('نوع الحقل','Field type'),f.type,'text',[{id:'text',name:t('نص','Text')},{id:'date',name:t('تاريخ','Date')},{id:'checkbox',name:t('تأكيد','Confirmation')}])}<label><input type="checkbox" name="templateField-${i}-required" ${f.required?'checked':''} />${t('إلزامي','Required')}</label>${button('template-field-remove',t('إزالة الحقل من الإصدار الجاري','Remove from current version'),String(i))}</div>`).join('')}${button('template-field-add',t('إضافة حقل','Add field'))}</fieldset>`;}
function profileContent(){const p=profile;if(tab==='personal')return (can('status')?form('cu-status',field('status',label('status'),p.status,'text',enums(['Prospect','Active','Suspended','Ended','Archived']))+field('reason',t('سبب تغيير الحالة','Status change reason'),'','textarea',null,true),t('حفظ الحالة','Save status')):'')+`<div class="cu-details">${table([t('البيان','Field'),t('القيمة','Value')],['birthDate','sponsor','residencyEmployer'].map(k=>[e(k),e(p[k]||'—')]))}<h3>${t('أرقام التواصل','Phone numbers')}</h3>${table([label('phone'),'WhatsApp',label('status'),t('التسويق','Marketing')],p.phones.map(x=>[`<a href="tel:${e(x.number)}">${e(x.number)}</a>`,x.whatsapp?'✓':'—',e(label(x.status)),e(label(x.marketingConsent))]))}<h3>${t('السكن وجهات الاتصال','Address & emergency contacts')}</h3><p>${e(p.address?.details||'—')}</p>${table([t('العناوين السابقة','Previous addresses'),t('تاريخ التحديث','Changed')],(p.addressHistory||[]).map(x=>[e(x.address.details||'—'),e(x.changedAt)]))}${table([t('الاسم','Name'),t('الدولة','Country'),label('phone')],p.emergencyContacts.map(x=>[e(x.name),e(x.country),e(x.phone)]))}</div>`;
if(tab==='documents')return `<p>${t('تخزين خاص مشفر؛ النسخ السابقة لا تستبدل. التنزيل والاكتمال ينتظران فحص الملف.','Private encrypted storage; old versions retained. Download/completion require a clean scan.')}</p>`+(can('documents')?form('cu-file',field('file',t('الصورة أو PDF','Image or PDF'),'','file',null,true)+field('title',t('العنوان','Title'),'','text',null,true)+field('kind',t('نوع المستند','Document kind'),'other','text',enums(['photo','emiratesId','passport','driving','residence','undertaking','other']))+field('parentId',t('نسخة سابقة (اختياري)','Previous version (optional)'),'','text',files.map(f=>({id:f.id,name:f.title+' v'+f.version})))+field('issuedOn',t('تاريخ الإصدار','Issued'),'','date')+field('expiresOn',t('تاريخ الانتهاء','Expiry'),'','date')):'')+table([t('المستند','Document'),t('النسخة','Version'),t('الفحص','Scan'),t('الإجراء','Action')],files.map(f=>[e(f.title),String(f.version),e(f.scanStatus),f.scanStatus==='clean'?button('download',t('عرض / تنزيل','View / download'),f.id):'—']));
if(tab==='notes')return (can('edit')?form('cu-note',field('type',t('النوع','Type'),'note','text',enums(['note','agreement','followup','promise']))+field('text',t('نص الملاحظة','Note'),'','textarea',null,true)+field('fileId',t('مستند مرتبط','Linked document'),'','text',files.map(f=>({id:f.id,name:f.title})))):'')+table([t('التاريخ','Date'),t('الموظف','Employee'),t('النوع','Type'),t('النص','Text')],p.timeline.filter(x=>x.kind==='note').map(x=>[e(x.createdAt),e(x.actorId),e(x.after.type),e(x.after.text)]));
if(tab==='calls')return (can('followup')?form('cu-call',field('phoneId',t('الرقم المستخدم','Number used'),'','text',p.phones.filter(x=>x.status==='valid').map(x=>({id:x.id,name:x.number})),true)+field('outcome',t('نتيجة الاتصال','Call outcome'),'no_answer','text',enums(['no_answer','off','confirmed','rescheduled']),true)+field('appointmentAt',t('تاريخ ووقت الموعد (عند التأكيد أو التغيير)','Appointment date/time (confirm/reschedule)'),'','datetime-local')+field('note',t('ملاحظة اختيارية','Optional note'),'','textarea')):'')+table([t('التاريخ','Date'),t('النتيجة','Outcome'),t('الموعد','Appointment'),t('الموظف','Employee')],p.timeline.filter(x=>x.kind==='call').map(x=>[e(x.createdAt),e(label(x.after.outcome)),e(x.after.appointmentAt||'—'),e(x.actorId)]))+(can('configure')?form('cu-config',field('noAnswerMinutes',t('إعادة تنبيه عدم الرد (دقيقة)','No-answer retry minutes'),'30','number')+field('offMinutes',t('الهاتف مغلق (دقيقة)','Phone-off retry minutes'),'60','number')+field('expiryDays',t('تنبيه انتهاء المستند (يوم)','Document expiry warning days'),'30','number')):'')+(can('followup')&&can('documents')?form('cu-cooperation',field('success',t('نتيجة واقعة التعاون الموثقة','Documented cooperation outcome'),'yes','text',[{id:'yes',name:t('تعاون','Cooperated')},{id:'no',name:t('لم يتعاون (بواقعة مثبتة)','Did not cooperate (documented)')}])+field('description',t('وصف الواقعة، وليس درجة يدوية','Incident description, not a manually entered score'),'','textarea',null,true)+field('sourceId',t('مرجع واقعة فريد لمنع تكرار الاحتساب','Unique incident reference to prevent duplicate counting'),'','text',null,true)+field('fileId',t('الدليل المفحوص','Scanned evidence'),'','text',files.filter(f=>f.scanStatus==='clean').map(f=>({id:f.id,name:f.title})),true)):'');
if(tab==='relations')return `<p>${t('لا تعقب للمواقع ولا مساواة بين العلاقة المثبتة والاشتباه. يلزم أساس مشروع لحفظ بيانات الحاضرين.','No location tracking; verified relationships remain distinct from unconfirmed links. Lawful collection basis required.')}</p>`+(can('relations')?form('cu-visit',field('customerIds',t('أرقام الملفات الأخرى (مفصولة بفاصلة)','Other file numbers (comma-separated)'),'','text',null,true)+field('occurredAt',t('تاريخ الزيارة','Visit date'),'','datetime-local',null,true)+field('certainty',t('درجة التحقق','Certainty'),'verified','text',[{id:'verified',name:t('مثبتة','Verified')},{id:'unconfirmed',name:t('غير مؤكدة','Unconfirmed')}])+field('lawfulBasis',t('أساس حفظ العلاقة','Lawful basis'),'','textarea',null,true)+field('note',t('ملاحظة','Note'),'','textarea')):'')+table([t('التاريخ','Date'),t('التحقق','Certainty'),t('المشاركون المخول عرضهم','Authorized participants')],relations.map(v=>[e(v.occurredAt),e(label(v.certainty)),v.people.map(x=>button('open',x.fullName+' #'+x.fileNumber,x.id)).join(' ')]));
if(tab==='undertakings')return `<p>${t('لا يحتسب التعهد مكتملاً إلا بعد اختيار النسخة الصحيحة المفحوصة وتوثيق التحقق. لكل إصدار سجل مستقل.','Completion needs a correct scanned document and documented verification. Each version retains its own history.')}</p>`+table([t('التعهد','Undertaking'),t('الإصدار','Version'),t('إلزامي','Required'),t('الحالة','State')],p.templates.map(x=>[e(x.name),String(x.version),x.required?'✓':'—',p.completeness.requirements.find(r=>r.id===x.id)?.complete?t('مكتمل','Complete'):t('لم يستكمل','Incomplete')]))+(can('undertaking_complete')?form('cu-undertaking',field('templateId',t('إصدار التعهد','Undertaking version'),'','text',p.templates.map(x=>({id:x.id,name:x.name+' v'+x.version})),true)+field('fileId',t('النسخة الموقعة المفحوصة','Scanned signed document'),'','text',files.filter(f=>f.scanStatus==='clean').map(f=>({id:f.id,name:f.title})),true)+field('verification',t('توثيق التحقق من المستند','Document verification'),'','textarea',null,true)+'<fieldset id="cu-dynamic-values"><legend>'+t('اختر إصدار التعهد لعرض حقوله','Select a version to display its fields')+'</legend></fieldset>'):'')+(can('undertaking_issue')||can('undertaking_edit')||can('undertaking_cancel')?form('cu-template',field('templateKey',t('التعهد عند التعديل/الإلغاء','Template to edit/cancel'),templateDraft.templateKey,'text',p.templates.map(x=>({id:x.template_key,name:x.name})))+field('action',t('الإجراء','Action'),templateDraft.action,'text',enums(['issue','edit','cancel']))+field('name',t('اسم التعهد','Template name'),templateDraft.name,'text',null,true)+field('description',t('الوصف','Description'),templateDraft.description,'textarea')+field('types',t('الفئة المستهدفة (فارغ للجميع)','Target type (blank for all)'),templateDraft.types,'text',enums(['owner','owner_driver','driver']))+templateFieldsHTML()+'<label><input type="checkbox" name="required" '+(templateDraft.required?'checked':'')+' />'+t('إلزامي','Required')+'</label>'):'');
if(tab==='financial')return `<p>${t('هذه الحركات البنكية المعتمدة المرتبطة فقط، وليست كشف مستحقات نهائياً. لا توجد جداول أقساط أو فواتير مكتملة؛ المبالغ غير المتاحة لا تُعرض صفراً. العملات والشركات لا تخلط.','Only linked posted bank movements, not a complete receivables statement. Installment/invoice schedules are unavailable; unknown amounts are not shown as zero. Currencies and companies remain separate.')}</p>`+form('cu-statement',field('from',t('من','From'),'','date')+field('to',t('إلى','To'),'','date')+field('companies',t('الشركات (معرّفات مفصولة بفاصلة، فارغ لجميع المخول)','Company IDs (comma-separated; blank for authorized companies)')))+`<div class="cu-actions">${can('export')?button('statement-csv','CSV')+button('statement-excel','Excel XML'):''}${can('print')?button('statement-print',t('طباعة / PDF','Print / PDF')):''}</div>`+(statement?`<p>${t('افتتاحيات الفترة حسب الشركة والعملة','Period openings by company/currency')}: ${e(JSON.stringify(statement.opening))}</p>`+table([t('الشركة','Company'),t('التاريخ','Date'),t('المرجع','Reference'),t('مدين','Debit'),t('دائن','Credit'),t('الرصيد','Balance'),t('العملة','Currency')],statement.rows.map(r=>[e(coName(r.company_id)),e(r.date),e(r.reference),e(r.debit),e(r.credit),e(r.balance),e(r.currency)])):'');
if(tab==='services')return table([t('رقم المركبة','Vehicle number'),t('اللوحة','Plate'),t('الشركة','Company'),t('فتح','Open')],(p.vehicles||[]).map(v=>[e(v.fileNumber),e(v.plate||'—'),e(coName(v.companyId)),button('open-vehicle',t('فتح المركبة','Open vehicle'),v.id)]))+button('vehicle-request',t('إنشاء طلب مركبة فعلي','Create vehicle request'))+`<p>${t('طلب المركبة الفعلي متاح بالزر أعلاه. الإقامة والطلب العام نقاط تكامل فقط، ولا يصدر حفظ النية عقداً أو التزاماً.','Use the button above for a real vehicle request. Residence/general services remain integration intents, issuing no contract or obligation.')}</p>`+(can('edit')?form('cu-service',field('type',t('نوع الطلب','Request type'),'vehicle','text',enums(['vehicle','residence','general']))+field('note',t('الملاحظة','Note'),'','textarea')+field('exceptionReason',t('سبب الاستثناء المعتمد لغير النشط (للمخول)','Authorized exception reason for inactive customer'),'','textarea')):'');
if(tab==='audit')return table([t('التاريخ','Date'),t('الموظف','Employee'),t('الحدث','Event'),t('قبل','Before'),t('بعد','After')],auditRows.map(r=>[e(r.createdAt),e(r.actorId),e(r.kind),`<pre>${e(JSON.stringify(r.before,null,2))}</pre>`,`<pre>${e(JSON.stringify(r.after,null,2))}</pre>`]));
return table([t('التاريخ','Date'),t('الحدث','Event'),t('الموظف','Employee'),t('فتح الأصل','Open source')],p.timeline.map(r=>[e(r.createdAt),e(label(r.kind)),e(r.actorId),button('event',t('عرض','View'),r.id)]));}
function importHTML(){return `<h2>${t('استيراد وهمي قابل للاستكمال — الحقيقي مغلق','Resumable synthetic import — real import locked')}</h2><p>${t('CSV وXLSX (الورقة الأولى) متاحان. المستندات القديمة تحتاج ربطاً يراجع قبل الاستيراد الحقيقي ونسخة احتياطية مستعادة. لا تستخدم بيانات حقيقية. الأعمدة: fullName,fileNumber,type,status,nationality,phone,notes','CSV and XLSX (first worksheet) supported. Legacy documents need reviewed mapping plus proven backup restore before real import. No real data. Columns: fullName,fileNumber,type,status,nationality,phone,notes')}</p>${form('cu-import',field('companyId',t('الشركة النشطة','Active company'),'','text',cap.companies.filter(c=>c.status==='Active'&&c.rights.includes('customer_import')),true)+field('csv',t('ملف CSV أو XLSX','CSV or XLSX file'),'','file',null,true))}${importJob?`<p>${e(importJob.status||'Preview')} — ${importJob.cursor||0} / ${importJob.total||importJob.count||0}</p><pre>${e(JSON.stringify(importJob.issues||[],null,2))}</pre>${button('import-run',t('اعتماد / استكمال الدفعة الوهمية (25 صفاً)','Confirm / resume synthetic batch (25 rows)'),importJob.id)}<pre>${e(JSON.stringify(importJob.results||[],null,2))}</pre>`:''}`;}
function renderPage(){const who=ABCentral?.actor?.id;if(who!==actor){reset();actor=who;}if(!ABCentral?.enabled)return `<section class="content-panel"><p>${t('وحدة العملاء تتطلب Backend مركزياً؛ لا بيانات عملاء في localStorage.','Customers require the central backend; no customer localStorage.')}</p></section>`;if(!cap&&!loading)queueMicrotask(load);if(!cap)return `<section class="content-panel">${e(notice||t('جارٍ التحقق…','Checking…'))}</section>`;if(!cap.available)return `<section class="content-panel"><p>${error('customerSchemaPending')}</p></section>`;return `<section class="content-panel cu-page"><p id="cu-notice" role="status">${e(notice)}</p>${editing?editor():tab==='import'?importHTML():tab==='drafts'?table([t('آخر تحديث','Last saved'),t('الاسم','Name'),t('فتح المسودة','Restore draft')],drafts.map(d=>[e(d.updatedAt),e(d.profile.fullName||'—'),button('draft',t('استعادة','Restore'),d.id)])):profile?header()+profileContent():listHTML()}</section>`;}
async function select(which){if(!leave())return;if(which==='new'){profile=null;editing=blank();dirty=false;draft=null;tab='personal';}else if(which==='drafts'){drafts=(await api('customer-drafts')).rows;profile=null;editing=null;tab='drafts';}else{profile=null;editing=null;tab=which==='import'?'import':'list';}redraw();}
function bind(){if(app.state.currentPage!=='customers')return;observer?.disconnect();if(!editing&&!profile&&tab==='list'){window.scrollTo(0,scroll);const n=document.getElementById('cu-sentinel');if(n&&list.length<total){observer=new IntersectionObserver(async entries=>{if(entries.some(x=>x.isIntersecting)&&!loading){loading=true;try{scroll=window.scrollY;await fetchRows(false);redraw();}catch(err){show(error(err.message));}finally{loading=false;}}},{rootMargin:'200px'});observer.observe(n);}}
 const ed=document.getElementById('cu-editor');ed?.addEventListener('input',()=>{readEditor();dirty=true;clearTimeout(timer);timer=setTimeout(autosave,1000);});ed?.querySelector('[name="emirate"]')?.addEventListener('change',()=>{readEditor();editing.address.areaId='';redraw();});ed?.querySelector('[name="companyId"]')?.addEventListener('change',()=>{if(profile){editing.companyId=profile.companyId;show(t('استخدم إجراء نقل الشركة مع السبب.','Use the company transfer action with a reason.'));redraw();}});
 ed?.addEventListener('submit',async ev=>{ev.preventDefault();if(ed._saving)return;ed._saving=true;clearTimeout(timer);readEditor();try{if(autoBusy){show(t('انتظر اكتمال حفظ المسودة ثم احفظ الملف.','Wait for draft save to finish, then save the profile.'));return;}const copy=structuredClone(editing),review=copy.duplicateReview;delete copy.duplicateReview;CustomerPolicy.validate(copy);const result=await api(profile?'customers/'+profile.id:'customers',profile?'PATCH':'POST',{profile:copy,...(profile?{revision:profile.revision}:{}),...(review?{duplicateReview:review}:{}),...(!profile&&draft?{draftId:draft.id}:{})});dirty=false;draft=null;notice=t('تم الحفظ والتحقق مركزياً.','Saved and verified centrally.');await fetchRows(true);const mode=ev.submitter?.dataset.saveMode;if(mode==='new'){profile=null;editing=blank();}else{profile=await api('customers/'+result.id);editing=null;tab=mode==='service'?'services':'personal';}redraw();}catch(err){show(error(err.message));}finally{ed._saving=false;}});
 document.getElementById('cu-filters')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));filters={...filters,...Object.fromEntries(Object.entries(f).filter(([,v])=>v!==''))};for(const [k,v]of Object.entries(f))if(v==='')delete filters[k];try{scroll=0;await fetchRows(true);await prefs();redraw();}catch(err){show(error(err.message));}});
 document.querySelectorAll('[data-cu-filter-search]').forEach(n=>n.oninput=()=>n.parentElement.querySelectorAll('label').forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(n.value.toLowerCase())));
 document.querySelectorAll('[data-cu-multi]').forEach(n=>n.onchange=async()=>{const name=n.dataset.cuMulti;filters[name]=[...document.querySelectorAll('[data-cu-multi="'+name+'"]:checked')].map(x=>x.value).join(',');try{scroll=0;await fetchRows(true);await prefs();redraw();}catch(err){show(error(err.message));}});
 document.querySelectorAll('[data-cu-column]').forEach(n=>n.onchange=async()=>{const k=n.dataset.cuColumn;columns=n.checked?[...columns,k]:columns.filter(x=>x!==k);if(!columns.length)columns=['fileNumber'];await prefs();redraw();});
 document.querySelectorAll('[data-cu]').forEach(b=>b.onclick=async()=>{b.disabled=true;const action=b.dataset.cu,key=b.dataset.id;try{if(action==='open-vehicle'){await VehicleUI.openNotification(key);return;}if(action==='vehicle-request'){await VehicleUI.startRequest(profile.id,profile.fullName);return;}if(action==='template-field-add'||action==='template-field-remove'){if(action==='open-vehicle'){await VehicleUI.openNotification(key);return;}if(action==='vehicle-request'){await VehicleUI.startRequest(profile.id,profile.fullName);return;}if(action==='template-field-add')templateDraft.fields.push({key:'field'+(templateDraft.fields.length+1),label:'',type:'text',required:false});else templateDraft.fields.splice(Number(key),1);redraw();return;}if(action==='duplicate-check'){readEditor();const copy=structuredClone(editing);delete copy.duplicateReview;CustomerPolicy.validate(copy);const r=await api('customers/duplicates','POST',copy),n=document.getElementById('cu-duplicates');n.textContent=(r.official?t('تطابق معرّف رسمي يحتاج مراجعة إضافية. ','Official identifier match needs additional review. '):'')+t('الملفات المشابهة لا تُدمج تلقائياً: ','Similar files are never merged automatically: ')+r.candidates.map(x=>'#'+x.fileNumber+' '+x.fullName).join(' — ');return;}if(action==='open'){await open(key);return;}if(action==='more'){scroll=window.scrollY;await fetchRows(false);redraw();return;}if(action==='back'||action==='cancel'){if(!leave())return;editing=null;dirty=false;profile=null;tab='list';redraw();return;}if(action==='edit'){editing=structuredClone(profile);for(const k of ['id','fileNumber','revision','completeness','rating','alerts','templates','timeline','financials','vehicles','integrationPending','addressHistory'])delete editing[k];if(can('documents'))files=(await api('customers/'+profile.id+'/files')).rows;dirty=false;redraw();return;}if(action==='tab'){if(!leave())return;tab=key;editing=null;dirty=false;if(['documents','notes','undertakings','calls'].includes(tab)&&can('documents'))files=(await api('customers/'+profile.id+'/files')).rows;if(tab==='relations'&&can('relations'))relations=(await api('customers/'+profile.id+'/relations')).rows;if(tab==='audit')auditRows=await api('customers/'+profile.id+'/audit');redraw();return;}if(action==='previous'||action==='next'){const i=list.findIndex(x=>x.id===profile.id),target=i+(action==='next'?1:-1);if(target>=list.length&&list.length<total)await fetchRows(false);if(list[target])await open(list[target].id);return;}if(action==='phone-add'||action==='phone-remove'||action==='emergency-add'||action==='emergency-remove'){readEditor();if(action==='phone-add')editing.phones.push({id:uid(),number:'',status:'unverified',primary:!editing.phones.length,whatsapp:false,marketingConsent:'unknown',consentAt:'',consentEvidence:''});if(action==='phone-remove')editing.phones.splice(Number(key),1);if(action==='emergency-add')editing.emergencyContacts.push({id:uid(),name:'',relationship:'',country:'',phone:'',whatsapp:false,homeCountryEmergency:false,lawfulBasis:''});if(action==='emergency-remove')editing.emergencyContacts.splice(Number(key),1);dirty=true;redraw();clearTimeout(timer);timer=setTimeout(autosave,1000);return;}if(action==='draft'){if(!leave())return;const d=drafts.find(x=>x.id===key);draft={id:d.id,revision:d.revision};editing=structuredClone(d.profile);profile=null;tab='personal';dirty=false;redraw();return;}if(action.startsWith('column-')){const i=columns.indexOf(key),j=i+(action==='column-up'?-1:1);if(i>=0&&j>=0&&j<columns.length)[columns[i],columns[j]]=[columns[j],columns[i]];await prefs();redraw();return;}if(action==='download'){const f=await api('customers/'+profile.id+'/files/'+key),bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));download(new Blob([bytes],{type:f.mime}),f.name);return;}if(action==='event'){const r=profile.timeline.find(x=>x.id===key);const n=document.getElementById('cu-notice');n.textContent=JSON.stringify(r.after,null,2);return;}if(action.startsWith('statement-')){await loadStatement(action.slice(10));return;}if(action==='import-run'){importJob={id:key,...await api('customer-imports/'+key+'/run','POST',{synthetic:true})};await fetchRows(true);redraw();return;}}catch(err){if(err.message!=='staleSession')show(error(err.message));}finally{if(b.isConnected)b.disabled=false;}});
 document.getElementById('cu-jump')?.addEventListener('submit',async ev=>{ev.preventDefault();try{const n=new FormData(ev.target).get('number'),r=await api('customers?'+new URLSearchParams({...filters,minNumber:n,maxNumber:n}));if(r.rows.length)await open(r.rows[0].id);else show(t('لا ملف مطابق ضمن الفلاتر والصلاحيات الحالية.','No matching file within current filters and permissions.'));}catch(err){show(error(err.message));}});
 for(const [fid,handler]of Object.entries({'cu-status':async f=>api('customers/'+profile.id+'/status','POST',{status:f.get('status'),reason:f.get('reason'),revision:profile.revision}),'cu-cooperation':async f=>api('customers/'+profile.id+'/cooperation','POST',{success:f.get('success')==='yes',description:f.get('description'),fileId:f.get('fileId'),sourceId:f.get('sourceId')}),'cu-note':async f=>api('customers/'+profile.id+'/notes','POST',{type:f.get('type'),text:f.get('text'),...(f.get('fileId')?{fileId:f.get('fileId')}:{})}),'cu-call':async f=>api('customers/'+profile.id+'/calls','POST',{phoneId:f.get('phoneId'),outcome:f.get('outcome'),note:f.get('note'),...(f.get('appointmentAt')?{appointmentAt:new Date(f.get('appointmentAt')).toISOString()}:{})}),'cu-config':async f=>api('customer-configuration','POST',{companyId:profile.companyId,noAnswerMinutes:Number(f.get('noAnswerMinutes')),offMinutes:Number(f.get('offMinutes')),expiryDays:Number(f.get('expiryDays'))}),'cu-service':async f=>api('customers/'+profile.id+'/service-intents','POST',{type:f.get('type'),note:f.get('note'),...(f.get('exceptionReason')?{exceptionReason:f.get('exceptionReason')}:{})}),'cu-template':async f=>api('customer-templates','POST',{companyId:profile.companyId,action:f.get('action'),name:f.get('name'),description:f.get('description'),types:String(f.get('types')||'').split(',').map(x=>x.trim()).filter(Boolean),required:f.has('required'),fields:templateDraft.fields,...(f.get('templateKey')?{templateKey:f.get('templateKey')}:{})}),'cu-undertaking':async f=>api('customers/'+profile.id+'/undertakings','POST',{templateId:f.get('templateId'),fileId:f.get('fileId'),verification:f.get('verification'),values:Object.fromEntries([...f.entries()].filter(([k])=>k.startsWith('dynamic-')).map(([k,v])=>[k.slice(8),v==='on'?true:v]))}),'cu-visit':async f=>{const ids=[profile.id];for(const n of String(f.get('customerIds')).split(',').map(x=>x.trim())){const r=await api('customers?minNumber='+encodeURIComponent(n)+'&maxNumber='+encodeURIComponent(n));if(!r.rows.length)throw Error('notFound');ids.push(r.rows[0].id);}return api('customer-visits','POST',{customerIds:ids,occurredAt:new Date(f.get('occurredAt')).toISOString(),certainty:f.get('certainty'),lawfulBasis:f.get('lawfulBasis'),note:f.get('note')});}})){document.getElementById(fid)?.addEventListener('submit',async ev=>{ev.preventDefault();const frm=ev.target;if(frm._saving)return;frm._saving=true;try{await handler(new FormData(frm));show(t('تم الحفظ على الخادم.','Saved on server.'));profile=await api('customers/'+profile.id);if(tab==='relations')relations=(await api('customers/'+profile.id+'/relations')).rows;redraw();}catch(err){show(error(err.message));}finally{frm._saving=false;}});}
 document.getElementById('cu-file')?.addEventListener('submit',async ev=>{ev.preventDefault();const frm=ev.target;if(frm._saving)return;frm._saving=true;try{const f=new FormData(frm),file=f.get('file');if(!file.size||file.size>10485760)throw Error('invalidFile');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('customers/'+profile.id+'/files','POST',{name:file.name,mime:file.type,base64,title:f.get('title'),kind:f.get('kind'),issuedOn:f.get('issuedOn'),expiresOn:f.get('expiresOn'),...(f.get('parentId')?{parentId:f.get('parentId')}:{})});files=(await api('customers/'+profile.id+'/files')).rows;notice=t('حُفظ الملف مركزياً؛ التنزيل يخضع للفحص.','File stored centrally; download requires scan.');redraw();}catch(err){show(error(err.message));}finally{frm._saving=false;}});
 document.getElementById('cu-statement')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await loadStatement('json');}catch(err){show(error(err.message));}});
 document.getElementById('cu-import')?.addEventListener('submit',async ev=>{ev.preventDefault();try{const f=new FormData(ev.target),source=f.get('csv');if(!source.size||source.size>5e6)throw Error('importTooLarge');const result=await api('customer-imports','POST',{companyId:f.get('companyId'),...(/\.xlsx$/i.test(source.name)?{xlsx:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(source);})}:{csv:await source.text()}),synthetic:true});importJob={id:result.id,...await api('customer-imports/'+result.id)};redraw();}catch(err){show(error(err.message));}});
 if(profile&&!editing&&can('transfer')&&!document.getElementById('cu-transfer')){const section=document.querySelector('.cu-page');const block=document.createElement('details');block.innerHTML=`<summary>${t('نقل العميل لشركة أخرى','Transfer customer to another company')}</summary>${form('cu-transfer',field('companyId',t('الشركة الجديدة','New company'),'','text',cap.companies.filter(c=>c.status==='Active'&&c.id!==profile.companyId&&c.rights.includes('customer_transfer')),true)+field('reason',t('سبب النقل','Transfer reason'),'','textarea',null,true))}`;section?.append(block);block.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{const f=new FormData(ev.target);await api('customers/'+profile.id+'/transfer','POST',{companyId:f.get('companyId'),reason:f.get('reason'),revision:profile.revision});profile=await api('customers/'+profile.id);await fetchRows(true);notice=t('نُقل الملف دون تغيير رقمه أو المعاملات السابقة.','Transferred without changing file number or prior transactions.');redraw();}catch(err){show(error(err.message));}};}
 const tf=document.getElementById('cu-template');tf?.addEventListener('input',()=>{const f=new FormData(tf);for(const k of ['name','description','types','action','templateKey'])templateDraft[k]=String(f.get(k)||'');templateDraft.required=f.has('required');templateDraft.fields=templateDraft.fields.map((v,i)=>({key:String(f.get('templateField-'+i+'-key')||''),label:String(f.get('templateField-'+i+'-label')||''),type:String(f.get('templateField-'+i+'-type')||'text'),required:f.has('templateField-'+i+'-required')}));});
 document.querySelector('#cu-template [name="templateKey"]')?.addEventListener('change',ev=>{const t=profile.templates.find(x=>x.template_key===ev.target.value);if(t){templateDraft={name:t.name,description:t.description,types:t.types[0]||'',required:t.required,action:'edit',templateKey:t.template_key,fields:structuredClone(t.fields)};redraw();}});
 document.querySelector('#cu-undertaking [name="templateId"]')?.addEventListener('change',ev=>{const selected=profile.templates.find(x=>x.id===ev.target.value),node=document.getElementById('cu-dynamic-values');if(node){node.innerHTML=(selected?.fields||[]).map(f=>f.type==='checkbox'?`<label><input type="checkbox" name="dynamic-${e(f.key)}" ${f.required?'required':''} />${e(f.label)}</label>`:field('dynamic-'+f.key,f.label,'',f.type==='date'?'date':'text',null,f.required)).join('');WorkspaceUI.enhance();}});
 WorkspaceUI.enhance();}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function loadStatement(format){const formEl=document.getElementById('cu-statement'),fields=Object.fromEntries(new FormData(formEl));const q=new URLSearchParams(Object.fromEntries(Object.entries({...fields,format:format==='print'?'print':format}).filter(([,v])=>v)));const r=await api('customers/'+profile.id+'/statement?'+q);if(['csv','excel'].includes(format))download(new Blob([r.data],{type:r.mime}),r.filename);else{statement=r;redraw();if(format==='print')window.print();}}
function notificationHTML(){queueMicrotask(async()=>{try{const rows=(await api('notifications')).rows;if(app.state.currentPage!=='notifications')return;const n=document.getElementById('cu-central-notifications');if(n)n.innerHTML=table([t('التاريخ','Date'),t('الحدث','Event'),t('الشركة','Company'),t('فتح','Open')],rows.map(r=>[e(r.createdAt),e(r.action),e(r.companyId),r.source==='personnel'?`<button type="button" class="ghost-btn" data-notice-personnel="${e(r.entityId)}">${t('شؤون الموظفين والمهام','Personnel & tasks')}</button>`:r.source==='ledger'?`<button type="button" class="ghost-btn" data-notice-ledger="${e(r.companyId)}">${t('الإدارة المالية','Financial management')}</button>`:r.source==='customer'?`<button type="button" class="ghost-btn" data-notice-customer="${e(r.entityId)}">${t('ملف العميل','Customer profile')}</button>`:r.source==='vehicle'?`<button type="button" class="ghost-btn" data-notice-vehicle="${e(r.entityId)}">${t('المركبة / الطلب','Vehicle / request')}</button>`:e(r.entityId)]));n?.querySelectorAll('[data-notice-personnel]').forEach(b=>b.onclick=()=>PersonnelUI.openNotification(b.dataset.noticePersonnel));n?.querySelectorAll('[data-notice-ledger]').forEach(b=>b.onclick=()=>LedgerUI.openNotification(b.dataset.noticeLedger));n?.querySelectorAll('[data-notice-vehicle]').forEach(b=>b.onclick=()=>VehicleUI.openNotification(b.dataset.noticeVehicle));n?.querySelectorAll('[data-notice-customer]').forEach(b=>b.onclick=async()=>{app.state.currentPage='customers';if(!cap)await load();await open(b.dataset.noticeCustomer);});}catch{}});return '<section class="content-panel"><h2>'+t('الإشعارات المركزية','Central notifications')+'</h2><div id="cu-central-notifications"></div></section>';}
root.CustomerUI={render:renderPage,bind,select,reset,leave,notificationHTML,canEnter:()=>ABCentral?.enabled&&(getCurrentUser()?.roleId==='owner'||(ABCentral.grants||[]).some(g=>g.userId===ABCentral.actor?.id&&g.entry?.action?.startsWith('customer_')))};
